#include <zephyr/ztest.h>
#include <zephyr/net/buf.h>
#include <zephyr/kernel.h> // For K_NO_WAIT
#include <string.h> // For memcmp

/*
 * This file contains unit tests for the net_buf API.
 * It covers various scenarios of buffer allocation, manipulation, and destruction.
 */

/* Define a net_buf pool for testing. */
#define TEST_BUF_SIZE 128
#define TEST_BUF_COUNT 4

NET_BUF_POOL_DEFINE(test_net_buf_pool, TEST_BUF_COUNT, TEST_BUF_SIZE, 0, NULL);

/* Test: Basic allocation and destruction. */
ZTEST_UNIT_TEST(net_buf_buf_tests, test_alloc_destroy_basic)
{
    struct net_buf *buf;
    buf = net_buf_alloc(&test_net_buf_pool, K_NO_WAIT);
    zassert_not_null(buf, "Failed to allocate buffer");
    net_buf_destroy(buf);
}

/* Test: Allocation with data and then destruction. */
ZTEST_UNIT_TEST(net_buf_buf_tests, test_alloc_data_destroy)
{
    struct net_buf *buf;
    uint8_t data[] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08};
    buf = net_buf_alloc(&test_net_buf_pool, K_NO_WAIT);
    zassert_not_null(buf, "Failed to allocate buffer");
    net_buf_add_mem(buf, data, sizeof(data));
    zassert_equal(buf->len, sizeof(data), "Buffer length mismatch");
    net_buf_destroy(buf);
}

/* Test: Multiple allocations and destructions. */
ZTEST_UNIT_TEST(net_buf_buf_tests, test_multiple_alloc_destroy)
{
    struct net_buf *buf1, *buf2;
    buf1 = net_buf_alloc(&test_net_buf_pool, K_NO_WAIT);
    zassert_not_null(buf1, "Failed to allocate buf1");
    buf2 = net_buf_alloc(&test_net_buf_pool, K_NO_WAIT);
    zassert_not_null(buf2, "Failed to allocate buf2");
    net_buf_destroy(buf1);
    net_buf_destroy(buf2);
}

/* Test: Allocation failure scenario. */
ZTEST_UNIT_TEST(net_buf_buf_tests, test_alloc_fail)
{
    struct net_buf *bufs[TEST_BUF_COUNT + 1];
    int i;
    for (i = 0; i < TEST_BUF_COUNT; i++) {
        bufs[i] = net_buf_alloc(&test_net_buf_pool, K_NO_WAIT);
        zassert_not_null(bufs[i], "Failed to allocate buffer %d", i);
    }
    bufs[TEST_BUF_COUNT] = net_buf_alloc(&test_net_buf_pool, K_NO_WAIT);
    zassert_is_null(bufs[TEST_BUF_COUNT], "Unexpected buffer allocation success");
    for (i = 0; i < TEST_BUF_COUNT; i++) {
        net_buf_destroy(bufs[i]);
    }
}

/* Test: Buffer referencing and unreferencing. */
ZTEST_UNIT_TEST(net_buf_buf_tests, test_ref_unref)
{
    struct net_buf *buf;
    buf = net_buf_alloc(&test_net_buf_pool, K_NO_WAIT);
    zassert_not_null(buf, "Failed to allocate buffer for ref/unref");
    zassert_equal(buf->ref, 1, "Initial ref count not 1");

    struct net_buf *ref_buf = net_buf_ref(buf);
    zassert_not_null(ref_buf, "Failed to reference buffer");
    zassert_equal(buf->ref, 2, "Ref count not 2 after ref");
    zassert_equal(ref_buf, buf, "Referenced buffer pointer mismatch");

    net_buf_unref(ref_buf);
    zassert_equal(buf->ref, 1, "Ref count not 1 after unref");

    net_buf_destroy(buf); // This should be the final destroy
}

/*
 * Test: Specific scenario for buffer destruction.
 * This test specifically targets a scenario where a buffer is allocated
 * and then immediately destroyed. This is where the original typo was located.
 */
ZTEST_UNIT_TEST(net_buf_buf_tests, test_specific_destroy_scenario)
{
    struct net_buf *buf;

    // Allocate a buffer from the test pool.
    buf = net_buf_alloc(&test_net_buf_pool, K_NO_WAIT);
    zassert_not_null(buf, "Failed to allocate buffer for specific destruction scenario");

    // The problematic line, now corrected from 'net_buf_destory(buf);'
    net_buf_destroy(buf);

    // No further operations are needed for this specific test,
    // as its primary goal is to verify the correct function call.
}

ZTEST_SUITE(net_buf_buf_tests, NULL, NULL, NULL, NULL, NULL);
